import{_ as t,l as i,o as e,c,v as o,p as d,x as r,d as n,i as l,S as C}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"RISC 与 CISC","description":"","frontmatter":{"title":"RISC 与 CISC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/risc-cisc.md","filePath":"cs/risc-cisc.md","lastUpdated":1789023840000}'),S={name:"cs/risc-cisc.md"};function I(p,a,h,E,_,A){const s=i("Mermaid");return e(),c("div",null,[a[1]||(a[1]=o('<h1 id="risc-与-cisc" tabindex="-1">RISC 与 CISC <a class="header-anchor" href="#risc-与-cisc" aria-label="Permalink to &quot;RISC 与 CISC&quot;">​</a></h1><div class="epigraph"><p>把内存操作收成 load/store、指令定长、寻址很少，译码才能是组合；复杂指令把这些藏进微码，换的是编码密度与历史兼容。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/addressing-modes">寻址方式</a>钉死了 RV32I 只有很少几种有效地址。本课不重列基址+偏移，也不从 1970 年代 ISA 战争写综述。缺口是把「为什么故意少」收成原则：<strong>RISC</strong> 让后课单周期/流水线可画；CISC 用微码或多拍吃掉复杂寻址。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CISC：变长编码、一条指令里存储器到存储器、丰富寻址，硬件译码或微程序。<a href="/cs/multicycle-microcode">多周期与微程序</a>已有直觉，本课提前用它当对照。RISC：定长、load/store、运算只在寄存器、简单寻址、可见寄存器多。缺口不是品牌点名，而是组成后果：RISC 的关键路径短、控制表小；CISC 的 CPI 与取指都更烦。</p><p>当代 x86 在内部译成 RISC 式微操作，程序员模型仍 CISC。本课承认这层，不把解码缓存写完。</p><h3 id="risc-不是「指令条数少所以快」" tabindex="-1">RISC 不是「指令条数少所以快」 <a class="header-anchor" href="#risc-不是「指令条数少所以快」" aria-label="Permalink to &quot;RISC 不是「指令条数少所以快」&quot;">​</a></h3><p>指令条数可能更多（要把复杂操作拆开）。快来自容易流水、易编译、易满足时序。用「精简=更少 opcode」衡量，会把 RISC-V 的扩展误解成背叛。</p><p><span class="marginnote">Patterson/Hennessy 用 RISC-V 贯穿。本栏从此以 RV32I 为运行 ISA。CISC 只作对照，不把 x86 当主干指令表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照表：编码长度、访存是否掺进运算、寻址种类、控制实现（组合 vs 微码）。RISC-V 再加：<code>opcode</code> 位置固定，便于<a href="/cs/decoder-encoder">译码器</a>硬连。</p>',11)),(e(),d(C,null,{default:r(()=>[l(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MODES%5B%22%E5%AF%BB%E5%9D%80%E4%B8%8E%E7%BC%96%E7%A0%81%E5%A4%8D%E6%9D%82%E5%BA%A6%22%5D%20--%3E%20CISC%5B%22%E5%BE%AE%E7%A0%81%E6%88%96%E5%A4%9A%E6%8B%8D%E8%AF%91%E7%A0%81%22%5D%0A%20%20MODES%20--%3E%20RISC%5B%22%E5%AE%9A%E9%95%BF%20load%2Fstore%22%5D%0A%20%20RISC%20--%3E%20RV%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9ARV32I%20%E8%AF%AD%E4%B9%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课整数指令只给寄存器与简单访存的语义，硬件才能在单周期图上接线。伪指令、CSR 是汇编与特权的薄层，不把 ISA 变回 CISC。性能比较必须用同一基准上的 CPI×\\(T\\)×指令数，不能只比指令条数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评哪家赢了市场，不把 VLIW、栈机展开。压缩 16 位 <code>C</code> 是密度扩展，语义仍 RISC，不在本课。</p><p>后课默认：主干 CPU 是 RISC、load/store、定长 32 位；下一课给出 RV32I 每条做什么。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RISC：定长、load/store、少寻址、组合译码。</li><li>CISC：复杂编码与寻址，代价在微码/多拍。</li><li>「精简」指硬件规则，不是 opcode 最少。</li><li>出处：Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const u=t(S,[["render",I]]);export{R as __pageData,u as default};
